static wsound89_i16 sat(wsound89_i32 v){if(v>32767)return 32767;if(v<-32768)return -32768;return(wsound89_i16)v;}static wsound89_i16 nz(wsoundfriction89_context*c){c->state=c->state*1103515245U+12345U;return(wsound89_i16)((c->state>>16)&65535U);}
wsound89_result wsoundfriction89_init(wsoundfriction89_context*c,wsound89_u32 seed){if(!c)return WSOUND89_EINVAL;c->state=seed?seed:0x46524943U;c->env=0;c->low=0;c->res1=c->res2=0;c->speed_q15=c->pressure_q15=c->roughness_q15=0;c->active=c->gate=0;c->material=WSOUNDFRICTION89_STEEL;return WSOUND89_OK;}
wsound89_result wsoundfriction89_start(wsoundfriction89_context*c,wsoundfriction89_material m,wsound89_u16 s,wsound89_u16 p,wsound89_u16 r){if(!c||(wsound89_u32)m>4U)return WSOUND89_EINVAL;c->material=m;c->speed_q15=s;c->pressure_q15=p;c->roughness_q15=r;c->env=22000;c->active=c->gate=1;return WSOUND89_OK;}void wsoundfriction89_set_motion(wsoundfriction89_context*c,wsound89_u16 s,wsound89_u16 p){if(c){c->speed_q15=s;c->pressure_q15=p;}}void wsoundfriction89_set_gate(wsoundfriction89_context*c,int g){if(c)c->gate=(wsound89_u8)(g?1:0);}
wsound89_i16 wsoundfriction89_process_sample(wsoundfriction89_context*c){wsound89_i32 n,hp,click,mix,shift;if(!c||!c->active)return 0;n=nz(c);shift=(c->material==WSOUNDFRICTION89_CLOTH)?6:(c->material==WSOUNDFRICTION89_CONCRETE?4:3);c->low+=(n-c->low)>>shift;hp=n-c->low;click=0;if((((wsound89_u32)n)&32767U)<((wsound89_u32)c->roughness_q15>>5))click=(n>>1);c->res1+=((hp-c->res1)>>2);c->res2+=((c->res1-c->res2)>>4);mix=((hp*(c->speed_q15>>1))>>15)+((click*c->pressure_q15)>>15);if(c->material==WSOUNDFRICTION89_STEEL)mix+=c->res1>>1;else if(c->material==WSOUNDFRICTION89_WOOD)mix+=c->res2;else if(c->material==WSOUNDFRICTION89_CLOTH)mix=(mix>>2)+(c->low>>4);mix=(mix*c->env)>>15;if(c->gate)c->env+=(28000-c->env)>>8;else c->env-=(c->env>>7)+10;if(c->env<20){c->env=0;c->active=0;}return sat(mix);}
